	private static <T> java.util.Map<String, T> boundedDropMap()
	{
		return new java.util.LinkedHashMap<String, T>()
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, T> eldest)
			{
				return size() > 128;
			}
		};
	}

