			configurePolling();
			if ("statsEnabled".equals(event.getKey()) || "discordDropsEnabled".equals(event.getKey())
				|| "pbRankingEnabled".equals(event.getKey()))
				clientThread.invokeLater(this::recoverPendingDrops);
		}
