		lastQuestPoints = -1;
		lastMaximumQuestPoints = -1;
		lastObservedRankTotalLevel = -1;
		questAccount = "";
		rankWidgetRefreshPending = false;
		cancelRankBankRefresh();
		rankSyncCompleted = false;
