			BufferedImage image = chatIconManager.getRankImage(title);
			if (image == null) return null;
			java.awt.Image scaled = image.getScaledInstance(20, 20, java.awt.Image.SCALE_SMOOTH);
			return new ImageIcon(scaled);
		}
		return null;
	}

