		actionFiller.setOpaque(false);
		actions.add(actionFiller);
		JPanel footer = new JPanel(new BorderLayout(3, 3));
		footer.add(actions, BorderLayout.NORTH);
		footer.add(status, BorderLayout.SOUTH);
		add(footer, BorderLayout.SOUTH);
