	void update(ClanTagsResponse response)
	{
		SwingUtilities.invokeLater(() ->
		{
			List<ClanTag> tags = response == null || response.tags == null ? new ArrayList<>() : response.tags;
			tag.removeAllItems();
			model.setRowCount(0);
			rows = new ArrayList<>();
			for (ClanTag clanTag : tags)
			{
				tag.addItem(clanTag);
				if (clanTag.members == null || clanTag.members.isEmpty())
				{
					model.addRow(new Object[]{clanTag.code, "—"});
					continue;
				}
				for (ClanTagMember member : clanTag.members)
				{
					rows.add(new Row(clanTag, member));
					model.addRow(new Object[]{clanTag.code, member.playerName});
				}
			}
			boolean canManage = response != null && response.canManage;
			create.setEnabled(canManage);
			addMember.setEnabled(canManage);
			deleteTag.setEnabled(canManage);
			removeMember.setEnabled(canManage);
			status.setText(canManage ? tags.size() + " etiqueta(s)" : "Somente Owner e Deputy Owner podem alterar");
		});
	}

	void setStatus(String text) { SwingUtilities.invokeLater(() -> status.setText(text)); }
	void clearCode() { SwingUtilities.invokeLater(() -> code.setText("")); }
	void clearMember() { SwingUtilities.invokeLater(() -> rsn.setText("")); }

	private String selectedColor()
	{
		String[] values = {"gold", "red", "blue", "green", "purple", "white"};
		int selected = color.getSelectedIndex();
		return selected < 0 || selected >= values.length ? "gold" : values[selected];
	}

	private static final class Row
	{
		private final ClanTag tag;
		private final ClanTagMember member;
		private Row(ClanTag tag, ClanTagMember member) { this.tag = tag; this.member = member; }
	}
}

package com.liveon;

import java.util.Collection;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.client.game.ItemStack;

/** Lets the reward widget cover clues for which RuneLite emits no loot event. */
final class ClueRewardGate
{
	private String officialFingerprint = "";
	private int officialTick = Integer.MIN_VALUE;

	void clear()
	{
		officialFingerprint = "";
		officialTick = Integer.MIN_VALUE;
	}

	void rememberOfficial(Collection<ItemStack> items, int tick)
	{
		officialFingerprint = fingerprint(items);
		officialTick = tick;
	}

	boolean shouldSendWidget(Collection<ItemStack> items, int rewardTick)
	{
		return !(officialTick >= rewardTick - 1 && officialTick <= rewardTick + 1
			&& fingerprint(items).equals(officialFingerprint));
	}

	private static String fingerprint(Collection<ItemStack> items)
	{
		Map<Integer, Long> quantities = new TreeMap<>();
		for (ItemStack item : items)
		{
			if (item != null && item.getQuantity() > 0)
			{
				quantities.merge(item.getId(), (long) item.getQuantity(), Long::sum);
			}
		}
		return quantities.toString();
	}
}

package com.liveon;

import java.io.IOException;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/** Owns the retry lifecycle for drop and pet notifications. */
@Slf4j
final class DropDeliveryClient implements AutoCloseable
{
	private static final int MAX_BACKOFF_EXPONENT = 6;
	private static final long MAX_RETRY_DELAY_SECONDS = 60L;
	private static final long RELAY_READ_TIMEOUT_SECONDS = 20L;

	private final OkHttpClient httpClient;
	private final Consumer<Runnable> onClientThread;
	private final ScheduledExecutorService executor;
	private final Set<Call> calls = ConcurrentHashMap.newKeySet();
	private final Set<ScheduledFuture<?>> retries = ConcurrentHashMap.newKeySet();
	private DropOutbox outbox;
	private DropDiagnosticJournal diagnosticJournal;
	private Consumer<String> deliveredCallback;
	enum Progress { QUEUED, FAILED, ACCEPTED, CANCELLED }
	private java.util.function.BiConsumer<Request, Progress> progressListener;
	private final Set<String> activeRecords = ConcurrentHashMap.newKeySet();
	private final AtomicBoolean closed = new AtomicBoolean();

	DropDeliveryClient(OkHttpClient httpClient, ClientThread clientThread, ScheduledExecutorService executor)
	{
		this(httpClient, clientThread::invokeLater, executor);
	}

	DropDeliveryClient(OkHttpClient httpClient, Consumer<Runnable> onClientThread,
		ScheduledExecutorService executor)
	{
		// The clan server can wait up to 15 seconds for its Discord relay. RuneLite's
		// shared client times out sooner, so give this isolated delivery client enough
		// time to receive the server's definitive forwarded/failed response.
		this.httpClient = httpClient.newBuilder()
			.readTimeout(RELAY_READ_TIMEOUT_SECONDS, TimeUnit.SECONDS)
			.build();
		this.onClientThread = onClientThread;
		this.executor = executor;
	}

	void setOutbox(DropOutbox outbox) { this.outbox = outbox; }
	void setDiagnosticJournal(DropDiagnosticJournal journal) { diagnosticJournal = journal; }
	void setDeliveredCallback(Consumer<String> callback) { deliveredCallback = callback; }
	void setProgressListener(java.util.function.BiConsumer<Request, Progress> listener) { progressListener = listener; }
	private void progress(Request request, Progress progress)
	{
		if (progressListener != null)
			onClientThread.accept(() -> { if (!closed.get()) progressListener.accept(request, progress); });
	}

	void recover(okhttp3.HttpUrl base, String player,
		java.util.function.Function<String, DropSessionGate.State> permission)
	{
		if (outbox == null || base == null || closed.get()) return;
		executor.execute(() -> {
			try {
				for (DropOutbox.Entry entry : outbox.pending(base, player)) {
					if (activeRecords.contains(entry.id)) continue;
					Request initial = entry.request(false).newBuilder().tag(String.class, entry.id).build();
					Request retry = entry.request(true).newBuilder().tag(String.class, entry.id).build();
					if (!activeRecords.add(entry.id)) continue;
					onClientThread.accept(() -> dispatch(initial, retry, entry.destination,
						() -> permission.apply(initial.url().encodedPath()), 0));
				}
			} catch (IOException | RuntimeException e) { log.warn("Unable to recover pending drop records", e); }
		});
	}

	void send(Request initialRequest, Request retryRequest, String destination,
		Supplier<DropSessionGate.State> retryAllowed)
	{
		if (closed.get()) return;
		if (outbox == null) {
			onClientThread.accept(() -> dispatch(initialRequest, retryRequest, destination, retryAllowed, 0));
			return;
		}
		executor.execute(() -> {
			Request initial = initialRequest;
			Request retry = retryRequest;
			try {
				String id = outbox.save(initial, retry, destination);
				trace(initial, "QUEUED", destination);
				activeRecords.add(id);
				initial = initial.newBuilder().tag(String.class, id).build();
				retry = retry.newBuilder().tag(String.class, id).build();
			} catch (IOException | RuntimeException e) {
				log.warn("Unable to persist pending drop; attempting network delivery", e);
				trace(initial, "PERSISTENCE_ERROR", destination);
			}
			final Request ready = initial, fallback = retry;
			onClientThread.accept(() -> dispatch(ready, fallback, destination, retryAllowed, 0));
		});
	}

	private void dispatch(Request request, Request retryRequest, String destination,
		Supplier<DropSessionGate.State> state, int attempt)
	{
		if (closed.get()) return;
		DropSessionGate.State current = state.get();
		progress(request, Progress.QUEUED);
		if (current == DropSessionGate.State.WAIT)
			scheduleRetry(request, retryRequest, destination, state, attempt);
		else if (current == DropSessionGate.State.READY)
			send(request, retryRequest, destination, state, attempt);
		else {
			progress(request, Progress.CANCELLED);
			trace(request, "CANCELLED", destination + " participation_disabled");
			String id = request.tag(String.class); if (id != null) activeRecords.remove(id);
		}
	}

	private void send(Request request, Request retryRequest, String destination,
		Supplier<DropSessionGate.State> retryAllowed, int attempt)
	{
		if (closed.get()) return;
		log.debug("Starting {} server request (attempt {})", destination, attempt + 1);
		trace(request, "SEND", destination + " attempt=" + (attempt + 1)
			+ " image=" + (request.header("X-Live-On-Image") == null ? "unknown"
				: request.header("X-Live-On-Image")));
		Call call = httpClient.newCall(request);
		calls.add(call);
		if (closed.get())
		{
			calls.remove(call);
			call.cancel();
			return;
		}
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call failedCall, IOException exception)
			{
				calls.remove(failedCall);
				if (!closed.get())
				{
					log.debug("Unable to deliver {} (attempt {})", destination, attempt + 1, exception);
					trace(request, "NETWORK_ERROR", destination + " attempt=" + (attempt + 1));
					progress(request, Progress.FAILED);
					scheduleRetry(request, retryRequest, destination, retryAllowed, attempt);
				}
			}

			@Override
			public void onResponse(Call completedCall, Response response) throws IOException
			{
				calls.remove(completedCall);
				try (Response ignored = response)
				{
					String responseBody = "";
					try
					{
						responseBody = response.body() == null ? "" : response.body().string();
					}
					catch (IOException exception)
					{
						// The status is already known: an unreadable diagnostic body must
						// not prevent retrying a transient error or removing a rejected image.
						log.debug("Unable to read {} response body (HTTP {})", destination, response.code(), exception);
					}
					if (!response.isSuccessful())
					{
						log.debug("{} delivery returned {}: {}", destination, response.code(), responseBody);
						trace(request, "HTTP", destination + " status=" + response.code());
						if (response.code() == 413 && request != retryRequest)
						{
							// Preserve the notification when a proxy rejects only its screenshot.
							trace(request, "IMAGE_REJECTED", destination + " status=413");
							onClientThread.accept(() -> dispatch(retryRequest, retryRequest, destination, retryAllowed,
								Math.min(1000, attempt + 1)));
							return;
						}
						if (response.code() == 408 || response.code() == 425
							|| response.code() == 429 || response.code() >= 500)
						{
							// 425 means the same event is still processing, not a confirmed failure.
							if (response.code() != 425) progress(request, Progress.FAILED);
							scheduleRetry(request, retryRequest, destination, retryAllowed, attempt);
						}
					}
					else
					{
						log.debug("{} server response (attempt {}): {}", destination, attempt + 1, responseBody);
						String result = responseBody.contains("\"filtered\"") ? "filtered"
							: responseBody.contains("\"duplicate\": true") || responseBody.contains("\"duplicate\":true")
								? "duplicate" : responseBody.contains("\"forwarded\": true")
									|| responseBody.contains("\"forwarded\":true") ? "relay_accepted" : "accepted";
						trace(request, "HTTP", destination + " status=" + response.code() + " result=" + result);
						progress(request, "filtered".equals(result) ? Progress.CANCELLED : Progress.ACCEPTED);
						if (deliveredCallback != null)
							onClientThread.accept(() -> { if (!closed.get()) deliveredCallback.accept(destination); });
						if (outbox != null) {
							String id = request.tag(String.class);
							try { outbox.complete(id); if (id != null) activeRecords.remove(id); }
							catch (IOException e) { log.warn("Unable to acknowledge persisted drop", e); }
						}
					}
				}
			}
		});
	}

	private void trace(Request request, String stage, String detail)
	{
		if (diagnosticJournal != null)
			diagnosticJournal.record(request.header("X-Live-On-Event"), stage, detail);
	}

	private synchronized void scheduleRetry(Request request, Request retryRequest, String destination,
		Supplier<DropSessionGate.State> retryAllowed, int attempt)
	{
		if (closed.get() || executor.isShutdown()) return;
		long delaySeconds = Math.min(MAX_RETRY_DELAY_SECONDS,
			1L << Math.min(attempt, MAX_BACKOFF_EXPONENT));
		AtomicReference<ScheduledFuture<?>> reference = new AtomicReference<>();
		try
		{
			ScheduledFuture<?> retry = executor.schedule(() -> {
				synchronized (DropDeliveryClient.this)
				{
					retries.remove(reference.get());
				}
				if (closed.get()) return;
				onClientThread.accept(() -> dispatch(request, retryRequest, destination, retryAllowed,
					Math.min(1000, attempt + 1)));
			}, delaySeconds, TimeUnit.SECONDS);
			reference.set(retry);
			retries.add(retry);
			if (closed.get())
			{
				retries.remove(retry);
				retry.cancel(false);
			}
		}
		catch (RejectedExecutionException ignored)
		{
			// The plugin is shutting down between the lifecycle check and scheduling.
		}
	}

	@Override
	public synchronized void close()
	{
		if (!closed.compareAndSet(false, true)) return;
		for (ScheduledFuture<?> retry : retries) retry.cancel(false);
		retries.clear();
		for (Call call : calls) call.cancel();
		calls.clear();
	}
}

package com.liveon;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.concurrent.Executor;
import lombok.extern.slf4j.Slf4j;

/** Small local delivery timeline. Never writes payloads, tokens, names or screenshots. */
@Slf4j
final class DropDiagnosticJournal
{
	private static final long MAX_BYTES = 1024 * 1024;
	private final Path file;
	private final Executor executor;

	DropDiagnosticJournal(Path file, Executor executor)
	{
		this.file = file;
		this.executor = executor;
	}

	void record(String eventId, String stage, String detail)
	{
		if (eventId == null || !eventId.matches("[0-9a-fA-F-]{36}")) return;
		String line = Instant.now() + " " + eventId + " " + stage + " " + detail + System.lineSeparator();
		try
		{
			executor.execute(() -> {
				try
				{
					Files.createDirectories(file.getParent());
					if (Files.exists(file) && Files.size(file) > MAX_BYTES)
						Files.move(file, file.resolveSibling(file.getFileName() + ".old"),
							java.nio.file.StandardCopyOption.REPLACE_EXISTING);
					Files.write(file, line.getBytes(StandardCharsets.UTF_8),
						StandardOpenOption.CREATE, StandardOpenOption.APPEND);
				}
				catch (IOException exception)
				{
					log.debug("Unable to write drop diagnostic journal", exception);
				}
			});
		}
		catch (java.util.concurrent.RejectedExecutionException ignored)
		{
			// Shutdown can race with a final event.
		}
	}
}

package com.liveon;

import java.awt.Image;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import java.util.function.Supplier;

/** Gives a pending frame a chance to arrive after loading before sending without it. */
final class DropFrameCapture implements AutoCloseable
{
	private static final long FRAME_WAIT_MILLIS = 2000;
	private final ScheduledExecutorService executor;
	private final Consumer<java.util.function.BooleanSupplier> onClientThread;
	private final Consumer<Consumer<Image>> requestFrame;
	private final Set<ScheduledFuture<?>> timeouts = ConcurrentHashMap.newKeySet();
	private final AtomicBoolean closed = new AtomicBoolean();

	DropFrameCapture(ScheduledExecutorService executor,
		Consumer<java.util.function.BooleanSupplier> onClientThread,
		Consumer<Consumer<Image>> requestFrame)
	{
		this.executor = executor;
		this.onClientThread = onClientThread;
		this.requestFrame = requestFrame;
	}

	void capture(Supplier<DropSessionGate.State> state, Consumer<Image> delivery)
	{
		if (closed.get()) return;
		AtomicBoolean delivered = new AtomicBoolean();
		Consumer<Image> finish = image -> {
			if (closed.get()) return;
			onClientThread.accept(DropSessionGate.task(state, () -> {
				if (!closed.get() && delivered.compareAndSet(false, true)) delivery.accept(image);
			}));
		};
		try
		{
			requestFrame.accept(finish);
			// A loading screen can delay the frame beyond this first timeout. Wait
			// for the session to become ready, then give the frame another chance.
			schedule(() -> onClientThread.accept(DropSessionGate.task(state, () -> {
				if (!delivered.get() && !closed.get()) schedule(() -> finish.accept(null));
			})));
		}
		catch (RuntimeException exception)
		{
			// A failed frame request must not lose the accepted loot event.
			finish.accept(null);
		}
	}

	private void schedule(Runnable action)
	{
		if (closed.get()) return;
		AtomicReference<ScheduledFuture<?>> reference = new AtomicReference<>();
		ScheduledFuture<?> future = executor.schedule(() -> {
			timeouts.remove(reference.get());
			if (!closed.get()) action.run();
		}, FRAME_WAIT_MILLIS, TimeUnit.MILLISECONDS);
		reference.set(future);
		timeouts.add(future);
		if (closed.get() && timeouts.remove(future)) future.cancel(false);
	}

	@Override public void close()
	{
		if (!closed.compareAndSet(false, true)) return;
		for (ScheduledFuture<?> future : timeouts) future.cancel(false);
		timeouts.clear();
	}
}

package com.liveon;

import java.util.function.IntToLongFunction;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/** Item values used consistently for Discord and MVP drop decisions. */
final class DropItemPricing
{
	private DropItemPricing() {}

	static long unitPrice(ItemManager itemManager, int itemId)
	{
		return unitPrice(itemId, itemManager::getItemPrice,
			id -> itemManager.getItemPriceWithSource(id, true),
			id -> itemManager.getItemComposition(id).getPrice());
	}

	static long unitPrice(int itemId, IntToLongFunction price, IntToLongFunction gePrice,
		IntToLongFunction storePrice)
	{
		long inferred = 0;
		if (itemId == ItemID.ARAXYTE_FANG)
		{
			inferred = gePrice.applyAsLong(ItemID.ETCHED_ARAXYTE_FANG);
		}
		else if (itemId == ItemID.NOXIOUS_HALBERD_PART_1
			|| itemId == ItemID.NOXIOUS_HALBERD_PART_2
			|| itemId == ItemID.NOXIOUS_HALBERD_PART_3)
		{
			inferred = gePrice.applyAsLong(ItemID.NOXIOUS_HALBERD) / 3;
		}
		else if (itemId == ItemID.MOKHAIOTL_CLOTH)
		{
			inferred = gePrice.applyAsLong(ItemID.CONFLICTION_GAUNTLETS)
				- gePrice.applyAsLong(ItemID.ZENYTE_BRACELET_ENCHANTED)
				- 10_000L * gePrice.applyAsLong(ItemID.DEMON_TEAR);
		}
		if (inferred > 0) return inferred;
		long direct = price.applyAsLong(itemId);
		return direct > 0 ? direct : Math.max(0L, storePrice.applyAsLong(itemId));
	}
}

package com.liveon;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.RequestBody;

/** Builds an initial notification with its screenshot-free retry body. */
final class DropMultipartPayload
{
	private static final MediaType PNG = MediaType.parse("image/png");
	final RequestBody initialBody;
	final RequestBody retryBody;

	private DropMultipartPayload(RequestBody initialBody, RequestBody retryBody)
	{
		this.initialBody = initialBody;
		this.retryBody = retryBody;
	}

	static DropMultipartPayload create(Gson gson, Map<String, Object> payload,
		Map<String, Object> embed, byte[] screenshot, String fileName)
	{
		if (screenshot == null)
		{
			RequestBody body = multipart(gson.toJson(payload), null, fileName);
			return new DropMultipartPayload(body, body);
		}
		Map<String, Object> image = new LinkedHashMap<>();
		image.put("url", "attachment://" + fileName);
		embed.put("image", image);
		RequestBody initial = multipart(gson.toJson(payload), screenshot, fileName);
		embed.remove("image");
		// The retry is only sent when the server rejects the image size (HTTP 413).
		Object fields = embed.get("fields");
		addScreenshotStatus(embed, screenshotStatus(SIZE_REJECTED, null));
		RequestBody retry = multipart(gson.toJson(payload), null, fileName);
		if (fields == null) embed.remove("fields");
		else embed.put("fields", fields);
		return new DropMultipartPayload(initial, retry);
	}

	/** Screenshot failure codes shown in Discord; the full error stays in drop-diagnostics.log. */
	static final int CAPTURE_MISSING = 101;
	static final int ENCODE_OUT_OF_MEMORY = 201;
	static final int ENCODE_FAILED = 202;
	static final int SIZE_REJECTED = 301;
	static final int SEND_FAILED = 901;

	/** Only the error type is shown: exception messages can contain local paths. */
	static String screenshotStatus(int code, Throwable error)
	{
		return "indisponível (erro " + code + (error == null ? "" : " · " + error.getClass().getSimpleName()) + ")";
	}

	@SuppressWarnings("unchecked")
	static void addScreenshotStatus(Map<String, Object> embed, String status)
	{
		Object current = embed.get("fields");
		List<Object> fields = current instanceof List ? new ArrayList<>((List<Object>) current) : new ArrayList<>();
		Map<String, Object> field = new LinkedHashMap<>();
		field.put("name", "Print");
		field.put("value", "```\n" + status + "\n```");
		field.put("inline", false);
		fields.add(field);
		embed.put("fields", fields);
	}

	private static RequestBody multipart(String payloadJson, byte[] screenshot, String fileName)
	{
		MultipartBody.Builder builder = new MultipartBody.Builder().setType(MultipartBody.FORM)
			.addFormDataPart("payload_json", payloadJson);
		if (screenshot != null)
		{
			builder.addFormDataPart("file", fileName, RequestBody.create(PNG, screenshot));
		}
		return builder.build();
	}
}

package com.liveon;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import okhttp3.*;
import okio.Buffer;

/** Disk operations are invoked only from the delivery executor or OkHttp callbacks. */
final class DropOutbox
{
    private final Path directory;
    private final Gson gson;

    DropOutbox(Path directory, Gson gson) { this.directory = directory; this.gson = gson; }

    String save(Request initial, Request retry, String destination) throws IOException
    {
        Entry entry = new Entry();
        entry.id = UUID.randomUUID().toString();
        entry.url = initial.url().toString();
        entry.player = initial.header("X-Live-On-Player");
        entry.destination = destination;
        entry.eventId = initial.header("X-Live-On-Event");
        entry.initialImage = initial.header("X-Live-On-Image");
        entry.retryImage = retry.header("X-Live-On-Image");
        entry.body = body(initial);
        entry.retryBody = body(retry);
        entry.contentType = initial.body().contentType().toString();
        entry.retryContentType = retry.body().contentType().toString();
        write(entry);
        return entry.id;
    }

    private static String body(Request request) throws IOException
    {
        Buffer buffer = new Buffer();
        request.body().writeTo(buffer);
        return Base64.getEncoder().encodeToString(buffer.readByteArray());
    }

    private void write(Entry entry) throws IOException
    {
        Files.createDirectories(directory);
        Path target = directory.resolve(entry.id + ".json");
        Path temporary = directory.resolve(entry.id + ".tmp");
        Files.write(temporary, gson.toJson(entry).getBytes(StandardCharsets.UTF_8));
        try { Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE); }
        catch (AtomicMoveNotSupportedException e) { Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING); }
    }

    void complete(String id) throws IOException { if (id != null) Files.deleteIfExists(directory.resolve(id + ".json")); }

    List<Entry> pending(HttpUrl base, String player) throws IOException
    {
        List<Entry> result = new ArrayList<>();
        if (!Files.isDirectory(directory)) return result;
        try (DirectoryStream<Path> files = Files.newDirectoryStream(directory, "*.json"))
        {
            for (Path file : files)
            {
                try
                {
                    Entry entry = gson.fromJson(Files.readString(file), Entry.class);
                    if (entry == null || !file.getFileName().toString().equals(entry.id + ".json")
                        || entry.player == null || !entry.player.equalsIgnoreCase(player)) continue;
                    HttpUrl url = HttpUrl.parse(entry.url);
                    if (url == null || !url.scheme().equals(base.scheme()) || !url.host().equals(base.host())
                        || url.port() != base.port() || url.query() != null) continue;
                    boolean allowed = false;
                    for (String path : new String[] {"stats/drops", "stats/pbs", "notifications/discord", "notifications/bingo"})
                        allowed |= url.equals(base.newBuilder().addPathSegments(path).build());
                    if (allowed) { entry.request(false); entry.request(true); result.add(entry); }
                }
                catch (IOException | RuntimeException malformed) { /* Retain unreadable records for diagnosis. */ }
            }
        }
        return result;
    }

    static final class Entry
    {
        String id, url, player, destination, eventId, initialImage, retryImage,
            body, retryBody, contentType, retryContentType;
        Request request(boolean retry)
        {
            return new Request.Builder().url(url).header("X-Live-On-Player", player)
                .header("Authorization", "LiveOnPlayer " + player)
                .header("X-Live-On-Event", eventId == null ? "" : eventId)
                .header("X-Live-On-Image", (retry ? retryImage : initialImage) == null
                    ? "unknown" : (retry ? retryImage : initialImage))
                .post(RequestBody.create(MediaType.parse(retry ? retryContentType : contentType),
                    Base64.getDecoder().decode(retry ? retryBody : body))).build();
        }
    }
}

package com.liveon;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.OptionalDouble;
import java.util.OptionalInt;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Data;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Reads the same OSRS Wiki-derived NPC drop-rate data used by Dink.
 * The bundled data and transformation are retained under Dink's BSD-2 license.
 */
@Slf4j
@Singleton
class DropRarityService
{
	private final ItemManager itemManager;
	private final Map<String, Collection<RareDrop>> dropsBySource = new HashMap<>();

	@Inject
	DropRarityService(Gson gson, ItemManager itemManager)
	{
		this.itemManager = itemManager;
		try (InputStream stream = getClass().getResourceAsStream("/npc_drops.json");
			 Reader reader = new InputStreamReader(Objects.requireNonNull(stream), StandardCharsets.UTF_8))
		{
			Map<String, List<RawDrop>> raw = gson.fromJson(reader,
				new TypeToken<Map<String, List<RawDrop>>>() { }.getType());
			raw.forEach((source, drops) -> dropsBySource.put(source, drops.stream()
				.map(RawDrop::transform)
				.flatMap(Collection::stream)
				.collect(Collectors.toCollection(ArrayList::new))));
		}
		catch (Exception exception)
		{
			log.debug("Unable to load NPC drop rarity data", exception);
		}
	}

	OptionalDouble getRarity(String source, int itemId, int quantity)
	{
		ItemComposition composition = itemManager.getItemComposition(itemId);
		int canonical = composition.getNote() != -1 ? composition.getLinkedNoteId() : itemId;
		String itemName = composition.getMembersName();
		Set<Integer> variants = new HashSet<>(ItemVariationMapping.getVariations(ItemVariationMapping.map(canonical)));
		return dropsBySource.getOrDefault(source, Collections.emptyList()).stream()
			.filter(drop -> drop.minQuantity <= quantity && quantity <= drop.maxQuantity)
			.filter(drop -> drop.itemId == itemId || (variants.contains(drop.itemId)
				&& itemName.equals(itemManager.getItemComposition(drop.itemId).getMembersName())))
			.mapToDouble(RareDrop::getProbability)
			.reduce(Double::sum);
	}

	OptionalDouble getRarityByItemName(String source, String itemName)
	{
		if (source == null || itemName == null) return OptionalDouble.empty();
		return dropsBySource.getOrDefault(source, Collections.emptyList()).stream()
			.filter(drop -> itemName.equalsIgnoreCase(itemManager.getItemComposition(drop.itemId).getMembersName()))
			.mapToDouble(RareDrop::getProbability)
			.reduce(Double::sum);
	}

	OptionalInt findItemId(String source, String itemName)
	{
		if (source == null || itemName == null) return OptionalInt.empty();
		return dropsBySource.getOrDefault(source, Collections.emptyList()).stream()
			.filter(drop -> itemName.equalsIgnoreCase(itemManager.getItemComposition(drop.itemId).getMembersName()))
			.mapToInt(RareDrop::getItemId)
			.findFirst();
	}

	@Value
	private static class RareDrop
	{
		int itemId;
		int minQuantity;
		int maxQuantity;
		double probability;
	}

	@Data
	private static class RawDrop
	{
		@SerializedName("i") private int itemId;
		@SerializedName("r") private Integer rolls;
		@SerializedName("d") private double denominator;
		@SerializedName("q") private Integer quantity;
		@SerializedName("m") private Integer quantityMin;
		@SerializedName("n") private Integer quantityMax;

		Collection<RareDrop> transform()
		{
			int rounds = rolls == null ? 1 : rolls;
			int min = quantityMin == null ? quantity : quantityMin;
			int max = quantityMax == null ? quantity : quantityMax;
			double chance = 1.0 / denominator;
			if (rounds == 1)
			{
				return Collections.singletonList(new RareDrop(itemId, min, max, chance));
			}
			List<RareDrop> result = new ArrayList<>(rounds);
			for (int successes = 1; successes <= rounds; successes++)
			{
				double density = binomial(rounds, successes) * Math.pow(chance, successes)
					* Math.pow(1.0 - chance, rounds - successes);
				result.add(new RareDrop(itemId, min * successes, max * successes, density));
			}
			return result;
		}

		private static long binomial(int n, int k)
		{
			long result = 1;
			for (int i = 1; i <= k; i++) result = result * (n - k + i) / i;
			return result;
		}
	}
}

package com.liveon;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Map;
import java.util.WeakHashMap;
import javax.imageio.ImageIO;

/** Reuses the most recent frame encoding across drop destinations. */
final class DropScreenshotEncoder
{
	private static final int MAX_WIDTH = 1920;
	private static final int MAX_HEIGHT = 1080;
	private static final int MAX_ENCODED_BYTES = 7 * 1024 * 1024;
	private static final int MIN_DIMENSION = 640;
	private final Map<BufferedImage, byte[]> encodings = new WeakHashMap<>();

	synchronized byte[] encode(BufferedImage frame) throws IOException
	{
		if (encodings.containsKey(frame)) return encodings.get(frame);
		BufferedImage candidate = fit(frame, MAX_WIDTH, MAX_HEIGHT);
		byte[] encoded = encodePng(candidate);
		while (encoded != null && encoded.length > MAX_ENCODED_BYTES
			&& (candidate.getWidth() > MIN_DIMENSION || candidate.getHeight() > MIN_DIMENSION))
		{
			candidate = fit(candidate,
				Math.max(MIN_DIMENSION, candidate.getWidth() * 4 / 5),
				Math.max(MIN_DIMENSION, candidate.getHeight() * 4 / 5));
			encoded = encodePng(candidate);
		}
		encodings.put(frame, encoded);
		return encoded;
	}

	private static byte[] encodePng(BufferedImage image) throws IOException
	{
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		return ImageIO.write(image, "png", output) ? output.toByteArray() : null;
	}

	private static BufferedImage fit(BufferedImage source, int maxWidth, int maxHeight)
	{
		double scale = Math.min(1D, Math.min((double) maxWidth / source.getWidth(),
			(double) maxHeight / source.getHeight()));
		if (scale >= 1D) return source;
		int width = Math.max(1, (int) Math.round(source.getWidth() * scale));
		int height = Math.max(1, (int) Math.round(source.getHeight() * scale));
		BufferedImage resized = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = resized.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			graphics.drawImage(source, 0, 0, width, height, null);
		}
		finally
		{
			graphics.dispose();
		}
		return resized;
	}

	synchronized void clear()
	{
		encodings.clear();
	}
}

package com.liveon;

import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import net.runelite.api.GameState;

/** Separates temporary loading from revocation of an accepted drop's session. */
final class DropSessionGate
{
	enum State { READY, WAIT, CANCEL }

	static State evaluate(long originalGeneration, long currentGeneration,
		String originalAccount, String currentAccount, boolean enabled, GameState gameState)
	{
		if (!enabled || originalGeneration != currentGeneration || originalAccount == null
			|| originalAccount.isEmpty() || !originalAccount.equals(currentAccount)) return State.CANCEL;
		if (gameState == GameState.LOADING || gameState == GameState.CONNECTION_LOST) return State.WAIT;
		return gameState == GameState.LOGGED_IN ? State.READY : State.CANCEL;
	}

	/** ClientThread retains a false-returning task without blocking the game thread. */
	static BooleanSupplier task(Supplier<State> state, Runnable action)
	{
		return () -> {
			State current = state.get();
			if (current == State.WAIT) return false;
			if (current == State.READY) action.run();
			return true;
		};
	}
}

