package com.liveon;

import net.runelite.api.GameState;

/** A persisted request remains bound to its original account and destination. */
final class RecordDeliveryGate
{
	static DropSessionGate.State evaluate(String owner, String local, String authenticated,
		boolean enabled, boolean temporaryWorld, boolean rejected, GameState gameState)
	{
		if (!enabled || temporaryWorld || rejected || owner == null || owner.isEmpty())
			return DropSessionGate.State.CANCEL;
		if (gameState == GameState.LOGIN_SCREEN || gameState == GameState.HOPPING)
			return DropSessionGate.State.CANCEL;
		if (local == null || local.isEmpty()) return DropSessionGate.State.WAIT;
		if (!owner.equalsIgnoreCase(local)) return DropSessionGate.State.CANCEL;
		if (gameState != GameState.LOGGED_IN || !owner.equalsIgnoreCase(authenticated))
			return DropSessionGate.State.WAIT;
		return DropSessionGate.State.READY;
	}
}

package com.liveon;

import java.util.HashSet;
import java.util.Set;

/** Client-thread state. Only actual pending deliveries and confirmed failures can notify. */
final class RecoveryNotice
{
	enum Message { NONE, WAITING, RECOVERED }
	private final Set<String> pending = new HashSet<>();
	private final Set<String> failedRequests = new HashSet<>();
	private boolean warned;
	private boolean cancelled;
	private int accepted;
	private long emptySince = -1;
	private long lastWarning = Long.MIN_VALUE;

	void queued(String key) { pending.add(key); emptySince = -1; }
	void failed(String key) { queued(key); failedRequests.add(key); }
	void accepted(String key) { failedRequests.remove(key); if (pending.remove(key)) accepted++; }
	void cancelled(String key) { failedRequests.remove(key); if (pending.remove(key)) cancelled = true; }

	Message poll(long now, boolean authenticationFailed, boolean authenticated)
	{
		boolean failure = !failedRequests.isEmpty() || (authenticationFailed && !pending.isEmpty());
		if (failure && !pending.isEmpty() && !warned
			&& (lastWarning == Long.MIN_VALUE || now - lastWarning >= 60000L))
		{
			warned = true;
			lastWarning = now;
			return Message.WAITING;
		}
		if (!pending.isEmpty() || !authenticated) { emptySince = -1; return Message.NONE; }
		if (emptySince < 0) emptySince = now;
		if (now - emptySince < 5000L) return Message.NONE;
		boolean recovered = warned && accepted > 0 && !cancelled;
		warned = cancelled = false;
		accepted = 0;
		return recovered ? Message.RECOVERED : Message.NONE;
	}

	void reset()
	{
		pending.clear();
		failedRequests.clear();
		warned = cancelled = false;
		accepted = 0;
		emptySince = -1;
		lastWarning = Long.MIN_VALUE;
	}
}

package com.liveon;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

final class WomMembership
{
	static final int LIVE_ON_GROUP_ID = 1945;
	private static final Set<String> STAFF_ROLES = new HashSet<>(Arrays.asList(
		"owner",
		"deputy_owner",
		"overseer",
		"supervisor",
		"moderator",
		"administrator"
	));

	private WomMembership()
	{
	}

	static Result parse(Gson gson, String json)
	{
		Entry[] memberships = gson.fromJson(json, Entry[].class);
		if (memberships == null)
		{
			return Result.NOT_A_MEMBER;
		}

		for (Entry membership : memberships)
		{
			if (membership != null && membership.liveOnGroupId() == LIVE_ON_GROUP_ID)
			{
				String role = membership.role != null ? membership.role : membership.roleName;
				return new Result(true, role);
			}
		}
		return Result.NOT_A_MEMBER;
	}

	static boolean isStaffRole(String role)
	{
		if (role == null)
		{
			return false;
		}
		return STAFF_ROLES.contains(role.trim().toLowerCase(Locale.ROOT).replace('-', '_').replace(' ', '_'));
	}

	static boolean canPublishBroadcast(String role)
	{
		if (!isStaffRole(role))
		{
			return false;
		}
		String normalizedRole = role.trim().toLowerCase(Locale.ROOT).replace('-', '_').replace(' ', '_');
		return !"administrator".equals(normalizedRole);
	}

	static String normalizePlayerName(String playerName)
	{
		if (playerName == null)
		{
			return "";
		}
		return playerName.replace('\u00A0', ' ').trim();
	}

	static final class Result
	{
		private static final Result NOT_A_MEMBER = new Result(false, null);
		final boolean member;
		final String role;

		private Result(boolean member, String role)
		{
			this.member = member;
			this.role = role;
		}
	}

	private static final class Entry
	{
		private int groupId;
		private String role;
		private String roleName;
		private Group group;

		private int liveOnGroupId()
		{
			return groupId > 0 ? groupId : group == null ? -1 : group.id;
		}
	}

	private static final class Group
	{
		private int id;
	}
}

