/** Exercises the production session gate and HTTP retry client without external requests. */
public class DropLoadingRetryTest
{
	@Test
	public void raidRetriesSurviveLoadingAndKeepEventIdentity() throws Exception
	{
		for (String raid : new String[] {"Chambers of Xeric", "Theatre of Blood", "Tombs of Amascut"})
		{
			try (Wire wire = new Wire(503))
			{
				wire.send(raid);
				wire.nextCallback().run();
				assertEquals("with-image", wire.requests.poll(5, TimeUnit.SECONDS));
				Runnable retry = wire.nextCallback();
				wire.game.set(GameState.LOADING);
				retry.run();
				assertEquals(1, wire.attempts.get());
				assertFalse(wire.executor.getQueue().isEmpty());
				wire.game.set(GameState.LOGGED_IN);
				wire.nextCallback().run();
				assertEquals("with-image", wire.requests.poll(5, TimeUnit.SECONDS));
				assertEquals(2, wire.attempts.get());
			}
		}
	}

	@Test
	public void loadingBeforeFirstAttemptPreservesScreenshot() throws Exception
	{
		try (Wire wire = new Wire(200))
		{
			wire.game.set(GameState.LOADING);
			wire.send("clue");
			wire.nextCallback().run();
			assertEquals(0, wire.attempts.get());
			wire.game.set(GameState.LOGGED_IN);
			wire.nextCallback().run();
			assertEquals("with-image", wire.requests.poll(5, TimeUnit.SECONDS));
		}
	}

	@Test
	public void cancelledSessionDoesNotStartOrResumeRequest() throws Exception
	{
		for (boolean firstAttempt : new boolean[] {true, false})
		{
			try (Wire wire = new Wire(503))
			{
				wire.send("raid");
				if (!firstAttempt)
				{
					wire.nextCallback().run();
					assertNotNull(wire.requests.poll(5, TimeUnit.SECONDS));
				}
				wire.game.set(GameState.LOGIN_SCREEN);
				wire.nextCallback().run();
				assertEquals(firstAttempt ? 0 : 1, wire.attempts.get());
				assertTrue(wire.executor.getQueue().isEmpty());
			}
		}
	}

	@Test
	public void shutdownCancelsLoadingRetry() throws Exception
	{
		try (Wire wire = new Wire(200))
		{
			wire.game.set(GameState.LOADING);
			wire.send("raid");
			wire.nextCallback().run();
			wire.delivery.close();
			assertTrue(wire.executor.getQueue().isEmpty());
			assertEquals(0, wire.attempts.get());
		}
	}

	private static final class Wire implements AutoCloseable
	{
		final ScheduledThreadPoolExecutor executor = new ScheduledThreadPoolExecutor(1);
		final LinkedBlockingQueue<Runnable> callbacks = new LinkedBlockingQueue<>();
		final LinkedBlockingQueue<String> requests = new LinkedBlockingQueue<>();
		final AtomicInteger attempts = new AtomicInteger();
		final AtomicReference<GameState> game = new AtomicReference<>(GameState.LOGGED_IN);
		final OkHttpClient http;
		final DropDeliveryClient delivery;
		Wire(int firstStatus)
		{
			executor.setRemoveOnCancelPolicy(true);
			http = new OkHttpClient.Builder().addInterceptor(chain -> {
				assertEquals("original-drop", chain.request().header("Idempotency-Key"));
				int attempt = attempts.incrementAndGet();
				requests.add(chain.request().header("Payload-Kind"));
				return new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1)
					.code(attempt == 1 ? firstStatus : 200).message("local simulation")
					.body(ResponseBody.create(null, "{}")).build();
			}).build();
			delivery = new DropDeliveryClient(http, callbacks::add, executor);
		}
		void send(String source)
		{
			Request initial = new Request.Builder().url("https://example.invalid/drop")
				.header("Idempotency-Key", "original-drop").header("Payload-Kind", "with-image").build();
			delivery.send(initial, initial.newBuilder().header("Payload-Kind", "without-image").build(), source,
				() -> DropSessionGate.evaluate(1, 1, "Milico", "Milico", true, game.get()));
		}
		Runnable nextCallback() throws InterruptedException
		{
			Runnable callback = callbacks.poll(5, TimeUnit.SECONDS);
			assertNotNull("Expected scheduled delivery callback", callback);
			return callback;
		}
		public void close()
		{
			delivery.close();
			executor.shutdownNow();
			http.dispatcher().executorService().shutdownNow();
			http.connectionPool().evictAll();
		}
	}
}

package com.liveon;

import com.google.gson.Gson;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import okhttp3.MultipartBody;
import okio.Buffer;
import org.junit.Test;
import static org.junit.Assert.*;

public class DropMultipartPayloadTest
{
	@Test
	public void retryKeepsMetadataAndDropsScreenshot() throws Exception
	{
		Map<String, Object> embed = new LinkedHashMap<>();
		embed.put("title", "Loot Drop");
		Map<String, Object> payload = new LinkedHashMap<>();
		payload.put("idempotencyKey", "event-123");
		payload.put("playerName", "Milico");
		payload.put("embeds", Collections.singletonList(embed));

		DropMultipartPayload bodies = DropMultipartPayload.create(
			new Gson(), payload, embed, new byte[] {1, 2, 3}, "loot.png");

		assertEquals(2, ((MultipartBody) bodies.initialBody).size());
		assertEquals(1, ((MultipartBody) bodies.retryBody).size());
		String initialJson = bodyText((MultipartBody) bodies.initialBody);
		String retryJson = bodyText((MultipartBody) bodies.retryBody);
		assertTrue(initialJson.contains("attachment://loot.png"));
		assertFalse(retryJson.contains("attachment://loot.png"));
		assertTrue(retryJson.contains("event-123"));
		assertTrue(retryJson.contains("Milico"));
		assertFalse(embed.containsKey("image"));
		// Only the size-rejected retry says why the screenshot is missing; the embed is left as it was.
		assertTrue(retryJson.contains("erro 301"));
		assertFalse(initialJson.contains("erro 301"));
		assertFalse(embed.containsKey("fields"));
	}

	@Test
	public void screenshotStatusShowsCodeAndErrorTypeOnly()
	{
		assertEquals("indisponível (erro 101)", DropMultipartPayload.screenshotStatus(101, null));
		assertEquals("indisponível (erro 202 · IllegalArgumentException)", DropMultipartPayload.screenshotStatus(
			202, new IllegalArgumentException("C:\\Users\\someone\\secret")));
		Map<String, Object> embed = new LinkedHashMap<>();
		embed.put("fields", Collections.singletonList(Collections.singletonMap("name", "Total Value")));
		DropMultipartPayload.addScreenshotStatus(embed, "indisponível (erro 101)");
		assertEquals(2, ((java.util.List<?>) embed.get("fields")).size());
	}

	private static String bodyText(MultipartBody body) throws Exception
	{
		Buffer buffer = new Buffer();
		body.part(0).body().writeTo(buffer);
		return buffer.readUtf8();
	}
}

package com.liveon;

import com.google.gson.Gson;
import java.nio.file.*;
import java.util.*;
import okhttp3.*;
import okio.Buffer;
import org.junit.Test;
import static org.junit.Assert.*;

public class DropOutboxTest
{
    @Test public void actualTransportRecoversAfterShutdown() throws Exception
    {
        Path folder = Files.createTempDirectory("drop-transport-restart");
        java.util.concurrent.ScheduledExecutorService executor = java.util.concurrent.Executors.newSingleThreadScheduledExecutor();
        java.util.concurrent.BlockingQueue<Runnable> callbacks = new java.util.concurrent.LinkedBlockingQueue<>();
        java.util.concurrent.BlockingQueue<Request> requests = new java.util.concurrent.LinkedBlockingQueue<>();
        java.util.concurrent.atomic.AtomicInteger attempts = new java.util.concurrent.atomic.AtomicInteger();
        OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain -> {
            requests.add(chain.request());
            return new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1)
                .code(attempts.incrementAndGet() == 1 ? 503 : 200).message("test")
                .body(ResponseBody.create(null, "{}")).build();
        }).build();
        try {
            DropOutbox outbox = new DropOutbox(folder, new Gson());
            HttpUrl base = HttpUrl.parse("https://example.invalid/");
            Request request = new Request.Builder().url(base.resolve("stats/drops"))
                .header("X-Live-On-Player", "Tamzz")
                .header("X-Live-On-Event", "c3a471a5-c8ce-4695-bc5d-fcc7c525ef53")
                .post(RequestBody.create(MediaType.parse("application/json"), "{\"eventId\":\"fixed-event\"}")).build();
            try (DropDeliveryClient first = new DropDeliveryClient(http, callbacks::add, executor)) {
                first.setOutbox(outbox);
                first.send(request, request, "MVP", () -> DropSessionGate.State.READY);
                Runnable dispatch = callbacks.poll(5, java.util.concurrent.TimeUnit.SECONDS);
                assertNotNull(dispatch); dispatch.run();
                assertNotNull(requests.poll(5, java.util.concurrent.TimeUnit.SECONDS));
                assertNotNull(callbacks.poll(5, java.util.concurrent.TimeUnit.SECONDS));
            }
            assertEquals(1, outbox.pending(base, "Tamzz").size());
            try (DropDeliveryClient restarted = new DropDeliveryClient(http, callbacks::add, executor)) {
                restarted.setOutbox(new DropOutbox(folder, new Gson()));
                restarted.recover(base, "Tamzz", path -> DropSessionGate.State.READY);
                Runnable dispatch = callbacks.poll(5, java.util.concurrent.TimeUnit.SECONDS);
                assertNotNull(dispatch); dispatch.run();
                Request recovered = requests.poll(5, java.util.concurrent.TimeUnit.SECONDS);
                assertNotNull(recovered);
                Buffer body = new Buffer(); recovered.body().writeTo(body);
                assertEquals("{\"eventId\":\"fixed-event\"}", body.readUtf8());
                assertEquals("Tamzz", recovered.header("X-Live-On-Player"));
                assertEquals("c3a471a5-c8ce-4695-bc5d-fcc7c525ef53",
                    recovered.header("X-Live-On-Event"));
            }
        } finally {
            executor.shutdownNow();
            http.dispatcher().executorService().shutdown();
            http.dispatcher().executorService().awaitTermination(5, java.util.concurrent.TimeUnit.SECONDS);
            http.connectionPool().evictAll();
            try (java.util.stream.Stream<Path> files = Files.list(folder)) {
                for (Path file : (Iterable<Path>) files::iterator) Files.delete(file);
            }
            Files.delete(folder);
        }
    }

    @Test public void restartPreservesBodyIdentityAndIdempotency() throws Exception
    {
        Path folder = Files.createTempDirectory("drop-outbox-test");
        try {
            Gson gson = new Gson();
            HttpUrl base = HttpUrl.parse("https://example.invalid/");
            Request original = new Request.Builder().url(base.resolve("notifications/discord"))
                .header("X-Live-On-Player", "Tamzz").header("Authorization", "Bearer do-not-store")
                .post(RequestBody.create(MediaType.parse("application/json"),
                    "{\"idempotencyKey\":\"stable-drop\",\"playerName\":\"Tamzz\"}")).build();
            DropOutbox first = new DropOutbox(folder, gson);
            String id = first.save(original, original, "CM drop");
            assertFalse(Files.readString(folder.resolve(id + ".json")).contains("do-not-store"));
            DropOutbox restarted = new DropOutbox(folder, gson);
            assertTrue(restarted.pending(base, "Other Account").isEmpty());
            assertTrue(restarted.pending(HttpUrl.parse("https://other.invalid/"), "Tamzz").isEmpty());
            List<DropOutbox.Entry> pending = restarted.pending(base, "tamzz");
            assertEquals(1, pending.size());
            Request restored = pending.get(0).request(false);
            assertEquals("Tamzz", restored.header("X-Live-On-Player"));
            assertEquals("LiveOnPlayer Tamzz", restored.header("Authorization"));
            Buffer before = new Buffer(), after = new Buffer();
            original.body().writeTo(before); restored.body().writeTo(after);
            assertEquals(before.readUtf8(), after.readUtf8());
            restarted.complete(id);
            assertTrue(restarted.pending(base, "Tamzz").isEmpty());
        } finally {
            try (java.util.stream.Stream<Path> files = Files.list(folder)) {
                for (Path file : (Iterable<Path>) files::iterator) Files.delete(file);
            }
            Files.delete(folder);
        }
    }

    @Test public void corruptRecordDoesNotHideFollowingRecords() throws Exception
    {
        Path folder = Files.createTempDirectory("drop-outbox-corrupt");
        try {
            Files.writeString(folder.resolve("broken.json"), "{");
            DropOutbox box = new DropOutbox(folder, new Gson());
            Request request = new Request.Builder().url("https://example.invalid/stats/drops")
                .header("X-Live-On-Player", "Milico")
                .post(RequestBody.create(MediaType.parse("application/json"), "{}")).build();
            String id = box.save(request, request, "MVP");
            assertEquals(1, box.pending(HttpUrl.parse("https://example.invalid/"), "Milico").size());
            box.complete(id);
            assertTrue(Files.exists(folder.resolve("broken.json")));
        } finally {
            try (java.util.stream.Stream<Path> files = Files.list(folder)) {
                for (Path file : (Iterable<Path>) files::iterator) Files.delete(file);
            }
            Files.delete(folder);
        }
    }
}

