        recovery.failed(1000);
        assertFalse(recovery.rejected());
        assertFalse(recovery.due(5999));
        assertTrue(recovery.due(6000));
        recovery.begin();
        recovery.failed(6000);
        assertFalse(recovery.due(15999));
        assertTrue(recovery.due(16000));
        recovery.resolved(true, 999999);
        assertFalse(recovery.rejected());
        assertFalse(recovery.due(Long.MAX_VALUE));
    }

    @Test public void confirmedNonMemberIsNotTreatedAsTransportFailure()
    {
        MembershipRecovery recovery = new MembershipRecovery();
        recovery.resolved(false, 61000);
        assertTrue(recovery.rejected());
        assertFalse(recovery.due(60000));
        assertTrue(recovery.due(61000));
        recovery.accountChanged();
        assertFalse(recovery.rejected());
        assertFalse(recovery.due(Long.MAX_VALUE));
    }

    // onGameTick calls begin() synchronously, right before verifyToken(), specifically so that
    // due() stops returning true on the very next tick instead of waiting for verifyToken()'s
    // own clientThread.invokeLater body to run and clear it a tick later. Without this, the
    // same due()==true condition keeps re-triggering verifyToken() every tick, cancelling and
    // restarting the WOM request each time.
    @Test public void beginImmediatelyStopsDueFromRetriggeringVerification()
    {
        MembershipRecovery recovery = new MembershipRecovery();
        recovery.failed(1000);
        assertTrue(recovery.due(6000));
        recovery.begin();
        assertFalse(recovery.due(6000));
        assertFalse(recovery.due(Long.MAX_VALUE));
    }

    @Test public void repeatedFailuresRemainBoundedAndRecoverable()
    {
        MembershipRecovery recovery = new MembershipRecovery();
        for (int i = 0; i < 1000; i++) {
            recovery.failed(1000);
            assertTrue(recovery.due(61000));
            assertFalse(recovery.rejected());
        }
        recovery.stale(1000);
        assertTrue(recovery.due(6000));
    }
}

package com.liveon;

import javax.swing.SwingUtilities;
import org.junit.Assert;
import org.junit.Test;

public class MvpPanelTest
{
	@Test
	public void rankingEntriesCompareDisplayedDataAndIgnorePositionChange()
	{
		com.google.gson.Gson gson = new com.google.gson.Gson();
		MvpDropEntry first = gson.fromJson("{\"player_name\":\"Leader\",\"total_value\":12000000,"
			+ "\"position\":1,\"top_drops\":[{\"item\":\"1x Fang\",\"value\":12000000,\"source\":\"Nex\"}]}",
			MvpDropEntry.class);
		MvpDropEntry same = gson.fromJson("{\"player_name\":\"Leader\",\"total_value\":12000000,"
			+ "\"position\":1,\"top_drops\":[{\"item\":\"1x Fang\",\"value\":12000000,\"source\":\"Nex\"}]}",
			MvpDropEntry.class);
		MvpDropEntry changed = gson.fromJson("{\"player_name\":\"Leader\",\"total_value\":13000000,"
			+ "\"position\":1,\"top_drops\":[{\"item\":\"1x Fang\",\"value\":13000000,\"source\":\"Nex\"}]}",
			MvpDropEntry.class);
		first.setPositionChange(2);
		Assert.assertEquals(first, same);
		Assert.assertNotEquals(first, changed);
	}

	@Test
	public void populatedDropsKeepSourceTooltipsAndLimitToFive() throws Exception
	{
		StringBuilder json = new StringBuilder("{\"player_name\":\"Leader\",\"total_value\":12000000,\"top_drops\":[");
		for (int index = 1; index <= 6; index++)
		{
			if (index > 1) json.append(',');
			json.append("{\"item\":\"Long example drop ").append(index)
				.append("\",\"source\":\"Example boss\",\"value\":2000000}");
		}
		MvpDropEntry entry = new com.google.gson.Gson().fromJson(json.append("]}").toString(), MvpDropEntry.class);
		MvpPanel[] panel = new MvpPanel[1];
		SwingUtilities.invokeAndWait(() -> {
			panel[0] = new MvpPanel(null);
			panel[0].updateDropRanking(java.util.Collections.singletonList(entry), null);
			panel[0].toggleDropExpansion("Leader");
		});
		SwingUtilities.invokeAndWait(() -> {
			java.util.List<String> tips = new java.util.ArrayList<>();
			collectTips(panel[0], tips);
			for (int index = 1; index <= 5; index++)
			{
				Assert.assertTrue(tips.contains("Long example drop " + index + " • Example boss"));
			}
			Assert.assertFalse(tips.contains("Long example drop 6 • Example boss"));
		});
	}

	@Test
	public void populatedEfficiencyDetailsKeepTooltipsAndLimitToFive() throws Exception
	{
		com.google.gson.Gson gson = new com.google.gson.Gson();
		MvpEfficiencyEntry entry = gson.fromJson("{\"player_name\":\"Leader\",\"gained\":21,\"breakdown\":["
			+ "{\"metric\":\"chambers_of_xeric_challenge_mode\",\"gained\":6},"
			+ "{\"metric\":\"nex\",\"gained\":5},{\"metric\":\"zulrah\",\"gained\":4},"
			+ "{\"metric\":\"vorkath\",\"gained\":3},{\"metric\":\"the_mimic\",\"gained\":2},"
			+ "{\"metric\":\"excluded_sixth\",\"gained\":1}]}", MvpEfficiencyEntry.class);
		MvpPanel[] panel = new MvpPanel[1];
		SwingUtilities.invokeAndWait(() -> {
			panel[0] = new MvpPanel(null);
			panel[0].updateEfficiencyRankings(java.util.Collections.singletonList(entry), null,
				java.util.Collections.emptyList(), null);
			panel[0].toggleEfficiencyExpansion("Leader", "EHB");
		});
		SwingUtilities.invokeAndWait(() -> {
			java.util.List<String> tips = new java.util.ArrayList<>();
			collectTips(panel[0], tips);
			for (String metric : new String[]{"chambers_of_xeric_challenge_mode", "nex", "zulrah", "vorkath", "the_mimic"})
			{
				Assert.assertTrue(metric, tips.contains(metric));
			}
			Assert.assertFalse(tips.contains("excluded_sixth"));
		});
	}

	private static void collectTips(java.awt.Component component, java.util.List<String> tips)
	{
		if (component instanceof javax.swing.JComponent)
		{
			tips.add(((javax.swing.JComponent) component).getToolTipText());
		}
		if (component instanceof java.awt.Container)
		{
			for (java.awt.Component child : ((java.awt.Container) component).getComponents()) collectTips(child, tips);
		}
	}

	@Test
	public void dropExpansionStartsClosedAndKeepsOnlyOnePlayerOpen() throws Exception
	{
		MvpPanel panel = new MvpPanel(null);
		Assert.assertFalse(panel.isDropExpanded("Leader"));

		panel.toggleDropExpansion("Leader");
		Assert.assertTrue(panel.isDropExpanded("leader"));

		panel.toggleDropExpansion("Second");
		Assert.assertFalse(panel.isDropExpanded("Leader"));
		Assert.assertTrue(panel.isDropExpanded("Second"));

		panel.toggleDropExpansion("Second");
		Assert.assertFalse(panel.isDropExpanded("Second"));
		SwingUtilities.invokeAndWait(() -> { });
	}

	@Test
	public void efficiencyExpansionIsIndependentForEhbAndEhp() throws Exception
	{
		MvpPanel panel = new MvpPanel(null);
		panel.toggleEfficiencyExpansion("Boss Player", "EHB");
		panel.toggleEfficiencyExpansion("Skill Player", "EHP");

		Assert.assertTrue(panel.isEfficiencyExpanded("Boss Player", "EHB"));
		Assert.assertTrue(panel.isEfficiencyExpanded("Skill Player", "EHP"));
		Assert.assertFalse(panel.isEfficiencyExpanded("Boss Player", "EHP"));

		panel.toggleEfficiencyExpansion("Other Boss Player", "EHB");
		Assert.assertFalse(panel.isEfficiencyExpanded("Boss Player", "EHB"));
		Assert.assertTrue(panel.isEfficiencyExpanded("Other Boss Player", "EHB"));
		Assert.assertTrue(panel.isEfficiencyExpanded("Skill Player", "EHP"));
		SwingUtilities.invokeAndWait(() -> { });
	}

	@Test
	public void monthTotalLineIsHiddenUntilServerSendsTotal()
	{
		org.junit.Assert.assertNull(MvpPanel.monthTotalText(0));
		org.junit.Assert.assertEquals(
			"<html>Total do clan no mês: <font color='#a6e22e'>12.40B</font></html>",
			MvpPanel.monthTotalText(12_400_000_000L));
	}
}

package com.liveon;

import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.BooleanSupplier;
import net.runelite.api.GameState;
import net.runelite.client.game.ItemStack;
import net.runelite.http.api.loottracker.LootRecordType;
import org.junit.Test;
import static org.junit.Assert.*;

public class NpcLootEventGateTest
{
	private static final List<ItemStack> COW_LOOT = Arrays.asList(new ItemStack(526, 1),
		new ItemStack(2132, 1), new ItemStack(1739, 1));

	@Test
	public void splitStacksMatchTheirGroupedTrackerEvent()
	{
		NpcLootEventGate gate = new NpcLootEventGate();
		gate.recordPrimary("Milico", "Cow", Arrays.asList(new ItemStack(526, 1), new ItemStack(526, 2)), 100);
		assertTrue(gate.consumePrimary("Milico", "Cow", Arrays.asList(new ItemStack(526, 3)), 100));
		assertFalse(gate.consumePrimary("Milico", "Cow", Arrays.asList(new ItemStack(526, 3)), 100));
	}

	@Test
	public void trackerOnlyLootWaitsForLoadingThenSendsOnce()
	{
		assertTrue(ClanMessagesPlugin.usesNpcTrackerFallback(LootRecordType.NPC, "Cow"));
		NpcLootEventGate gate = new NpcLootEventGate();
		AtomicReference<GameState> game = new AtomicReference<>(GameState.LOADING);
		AtomicInteger deliveries = new AtomicInteger();
		BooleanSupplier fallback = fallback(gate, game, deliveries, "Milico", "Cow", COW_LOOT, 100);
		assertFalse(fallback.getAsBoolean());
		assertEquals(0, deliveries.get());
		game.set(GameState.LOGGED_IN);
		assertTrue(fallback.getAsBoolean());
		assertEquals(1, deliveries.get());
	}

	@Test
	public void primaryBeforeTrackerSuppressesOnlyItsMatchingFallback()
	{
		NpcLootEventGate gate = new NpcLootEventGate();
		AtomicReference<GameState> game = new AtomicReference<>(GameState.LOGGED_IN);
		AtomicInteger deliveries = new AtomicInteger();
		gate.recordPrimary("Milico", "Cow", COW_LOOT, 100);
		assertTrue(fallback(gate, game, deliveries, "Milico", "Cow", COW_LOOT, 100).getAsBoolean());
		assertEquals(0, deliveries.get());
		// A later kill with the same loot and no primary event still goes through the fallback.
		assertTrue(fallback(gate, game, deliveries, "Milico", "Cow", COW_LOOT, 105).getAsBoolean());
		assertEquals(1, deliveries.get());
	}

	@Test
	public void extraCopiesFromOtherPluginsAreIgnoredForOneTick()
	{
		NpcLootEventGate gate = new NpcLootEventGate();
		AtomicReference<GameState> game = new AtomicReference<>(GameState.LOGGED_IN);
		AtomicInteger deliveries = new AtomicInteger();
		gate.recordPrimary("MeHZAO", "Hellhound", COW_LOOT, 100);
		for (int tick : new int[] {100, 100, 101})
		{
			assertTrue(fallback(gate, game, deliveries, "MeHZAO", "Hellhound", COW_LOOT, tick).getAsBoolean());
		}
		assertEquals(0, deliveries.get());
		assertFalse(gate.isRepeatOfConsumed("MeHZAO", "Hellhound", COW_LOOT, 102));
	}

	@Test
	public void trackerCopyOneTickLateOrEarlyIsSentOnce()
	{
		AtomicReference<GameState> game = new AtomicReference<>(GameState.LOGGED_IN);
		AtomicInteger deliveries = new AtomicInteger();
		NpcLootEventGate late = new NpcLootEventGate();
		primary(late, deliveries, "Milico", "Cow", COW_LOOT, 100);
		fallback(late, game, deliveries, "Milico", "Cow", COW_LOOT, 101).getAsBoolean();
		NpcLootEventGate early = new NpcLootEventGate();
		fallback(early, game, deliveries, "Milico", "Cow", COW_LOOT, 100).getAsBoolean();
		primary(early, deliveries, "Milico", "Cow", COW_LOOT, 101);
		assertEquals(2, deliveries.get());
	}

	@Test
	public void identicalKillsAreEachSentOnceInEitherOrder()
	{
		NpcLootEventGate gate = new NpcLootEventGate();
		AtomicReference<GameState> game = new AtomicReference<>(GameState.LOGGED_IN);
		AtomicInteger deliveries = new AtomicInteger();
		fallback(gate, game, deliveries, "Milico", "Cow", COW_LOOT, 100).getAsBoolean();
		fallback(gate, game, deliveries, "Milico", "Cow", COW_LOOT, 100).getAsBoolean();
		primary(gate, deliveries, "Milico", "Cow", COW_LOOT, 101);
		primary(gate, deliveries, "Milico", "Cow", COW_LOOT, 101);
		assertEquals(2, deliveries.get());
		primary(gate, deliveries, "Milico", "Cow", COW_LOOT, 110);
		assertEquals(3, deliveries.get());
	}

	@Test
	public void trackerBeforePrimaryWaitsAndThenAvoidsDuplicate()
	{
		NpcLootEventGate gate = new NpcLootEventGate();
		AtomicReference<GameState> game = new AtomicReference<>(GameState.LOADING);
		AtomicInteger deliveries = new AtomicInteger();
		BooleanSupplier fallback = fallback(gate, game, deliveries, "Milico", "Cow", COW_LOOT, 100);
		assertFalse(fallback.getAsBoolean());
		gate.recordPrimary("Milico", "Cow", COW_LOOT, 100);
		game.set(GameState.LOGGED_IN);
		assertTrue(fallback.getAsBoolean());
		assertEquals(0, deliveries.get());
	}

	@Test
	public void identicalKillsKeepTheirOwnPrimaryMatches()
	{
		NpcLootEventGate gate = new NpcLootEventGate();
		gate.recordPrimary("Milico", "Cow", COW_LOOT, 100);
		gate.recordPrimary("Milico", "Cow", COW_LOOT, 100);
		assertTrue(gate.consumePrimary("Milico", "Cow", COW_LOOT, 100));
		assertTrue(gate.consumePrimary("Milico", "Cow", COW_LOOT, 100));
		assertFalse(gate.consumePrimary("Milico", "Cow", COW_LOOT, 100));
	}

	@Test
	public void accountTickAndItemsDoNotStealAnotherDrop()
	{
		NpcLootEventGate gate = new NpcLootEventGate();
		gate.recordPrimary("Milico", "Cow", COW_LOOT, 100);
		assertFalse(gate.consumePrimary("Other", "Cow", COW_LOOT, 100));
		assertFalse(gate.consumePrimary("Milico", "Cow", COW_LOOT, 102));
		// Loot that shares no item with the primary belongs to another kill.
		assertFalse(gate.consumePrimary("Milico", "Cow", Arrays.asList(new ItemStack(995, 2)), 100));
		assertTrue(gate.consumePrimary("Milico", "Cow", COW_LOOT, 100));
	}

	@Test
	public void bonecrusherBonesAreTheOnlyItemLeftInEitherOrder()
	{
		// The ground shows only the drop; the server loot behind the tracker copy still lists the bones.
		List<ItemStack> ground = Arrays.asList(new ItemStack(21270, 1));
		List<ItemStack> tracker = Arrays.asList(new ItemStack(21270, 1), new ItemStack(526, 1));
		NpcLootEventGate gate = new NpcLootEventGate();
		gate.recordPrimary("Boramosso", "Greater abyssal demon", ground, 100);
		List<ItemStack> extra = gate.takePrimary("Boramosso", "Greater abyssal demon", tracker, 100);
		assertEquals(1, extra.size());
		assertEquals(526, extra.get(0).getId());
		gate.recordFallback("MeHZAO", "Hellhound", tracker, 100);
		assertTrue(gate.takeFallback("MeHZAO", "Hellhound", ground, 101).isEmpty());
	}

	@Test
	public void sharedItemMatchPrefersTheKillWithMostItemsInCommon()
	{
		NpcLootEventGate gate = new NpcLootEventGate();
		gate.recordPrimary("Milico", "Cow", Arrays.asList(new ItemStack(526, 1), new ItemStack(2132, 1)), 100);
		gate.recordPrimary("Milico", "Cow", Arrays.asList(new ItemStack(526, 1), new ItemStack(1739, 1)), 100);
		assertTrue(gate.consumePrimary("Milico", "Cow", Arrays.asList(new ItemStack(526, 1), new ItemStack(1739, 1)), 100));
		assertTrue(gate.consumePrimary("Milico", "Cow", Arrays.asList(new ItemStack(526, 1), new ItemStack(2132, 1)), 100));
	}

	@Test
	public void logoutCancelsWaitingFallbackAndSpecialNpcKeepsExistingRoute()
	{
		assertFalse(ClanMessagesPlugin.usesNpcTrackerFallback(LootRecordType.NPC, "Araxxor"));
		assertFalse(ClanMessagesPlugin.usesNpcTrackerFallback(LootRecordType.EVENT, "Chambers of Xeric"));
		NpcLootEventGate gate = new NpcLootEventGate();
		AtomicReference<GameState> game = new AtomicReference<>(GameState.LOADING);
		AtomicInteger deliveries = new AtomicInteger();
		BooleanSupplier fallback = fallback(gate, game, deliveries, "Milico", "Cow", COW_LOOT, 100);
		assertFalse(fallback.getAsBoolean());
		game.set(GameState.LOGIN_SCREEN);
		assertTrue(fallback.getAsBoolean());
		assertEquals(0, deliveries.get());
	}

	private static void primary(NpcLootEventGate gate, AtomicInteger deliveries, String account,
		String source, List<ItemStack> items, int tick)
	{
		List<ItemStack> uncovered = gate.takeFallback(account, source, items, tick);
		if (uncovered != null && uncovered.isEmpty()) return;
		gate.recordPrimary(account, source, items, tick);
		deliveries.incrementAndGet();
	}

	private static BooleanSupplier fallback(NpcLootEventGate gate, AtomicReference<GameState> game,
		AtomicInteger deliveries, String account, String source, List<ItemStack> items, int tick)
	{
		return DropSessionGate.task(() -> DropSessionGate.evaluate(1, 1, account, account, true, game.get()),
			() -> {
				if (gate.consumePrimary(account, source, items, tick)
					|| gate.isRepeatOfConsumed(account, source, items, tick)) return;
				gate.recordFallback(account, source, items, tick);
				deliveries.incrementAndGet();
			});
	}
}

package com.liveon;

import java.util.Map;
import java.util.Arrays;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class PbPayloadTest
{
	@Test
	public void filtersJadChallengesWithoutRemovingFightCave()
	{
		assertFalse(PbCategory.isAllowed("Jad Challenge"));
		assertFalse(PbCategory.isAllowed("Jad Challenge II"));
		assertFalse(PbCategory.isAllowed("Six Jad Challenge"));
		assertFalse(PbCategory.isAllowed("Fastest Wave time (former)"));
		assertFalse(PbCategory.isAllowed("TzHaar-Ket-Rak's Challenges"));
		assertFalse(PbCategory.isAllowed("TzHaar-Ket-Rak's First Challenge"));
		assertFalse(PbCategory.isAllowed("TzHaar-Ket-Rak's Fourth Challenge"));
		assertFalse(PbCategory.isAllowed("TzHaar Fight Cave", "Six Jad Challenge"));
		assertTrue(PbCategory.isAllowed("TzTok-Jad"));
		assertTrue(PbCategory.isAllowed("TzHaar Fight Cave"));
		assertTrue(PbCategory.isAllowed("Chambers of Xeric", "Challenge Mode"));
	}

	@Test
	public void treatsLegacyAndCanonicalSoloCategoriesAsEquivalent()
	{
		assertTrue(PbPanel.sameTeamSize(0, 1));
		assertTrue(PbPanel.sameTeamSize(1, 0));
		assertFalse(PbPanel.sameTeamSize(1, 5));
	}

	@Test
	public void readsPlainAndColoredBossPbMessages()
	{
		for (String message : Arrays.asList("Fight duration: 4:31.20 (new personal best)",
			"Fight duration: <col=ff0000>4:31.20</col> (new personal best)",
			"Subdued in 4:31.20 (new personal best)"))
		{
			assertEquals(271.2, (Double) ClanMessagesPlugin.parseChatNewPb(message).get("seconds"), 0.001);
		}
	}

	@Test
	public void recognizesCoxTeamAndNamedRaidTotals()
	{
		Map<String, Object> cox = ClanMessagesPlugin.parseChatNewPb(
			"Congratulations - your raid is complete!\nTeam size: 24+ players Duration: 36:04.20 (new personal best)");
		assertEquals(24, cox.get("teamSize"));
		assertEquals(2164.2, (Double) cox.get("seconds"), 0.001);
		Map<String, Object> toa = ClanMessagesPlugin.parseChatNewPb(
			"Tombs of Amascut: Expert Mode total completion time: 25:00 (new personal best)");
		assertEquals("Tombs of Amascut: Expert Mode", toa.get("boss"));
		assertEquals(1500.0, (Double) toa.get("seconds"), 0.001);
		// Theatre of Blood's total-completion line is now its own "Overall" PB category,
		// distinct from the room/challenge-time PB. It never carries a mode itself - that is
		// resolved later at submission time from whatever pendingPbMode the wave-complete
		// message (parsed elsewhere, moments earlier) already captured.
		Map<String, Object> tob = ClanMessagesPlugin.parseChatNewPb(
			"Theatre of Blood total completion time: 25:28.80 (new personal best)");
		assertEquals("Theatre of Blood", tob.get("boss"));
		assertEquals(1528.8, (Double) tob.get("seconds"), 0.001);
	}

	@Test
	public void readsOwnClanPbAnnouncementsAcrossActivitiesAndModes()
	{
		Map<String, Object> cox = ClanMessagesPlugin.parseClanPbAnnouncement(
			"Tammz has achieved a new Chambers of Xeric (Team Size: Solo) personal best: 16:46", "Tammz");
		assertEquals("Chambers of Xeric", cox.get("boss"));
		assertEquals("Normal", cox.get("mode"));
		assertEquals(0, cox.get("teamSize"));
		assertEquals(1006.0, (Double) cox.get("seconds"), 0.001);

		Map<String, Object> cm = ClanMessagesPlugin.parseClanPbAnnouncement(
			"Tammz has achieved a new Chambers of Xeric Challenge Mode (Team Size: 3) personal best: 35:53", "Tammz");
		assertEquals("Challenge Mode", cm.get("mode"));
		assertEquals(3, cm.get("teamSize"));
		Map<String, Object> tob = ClanMessagesPlugin.parseClanPbAnnouncement(
			"Tammz has achieved a new Theatre of Blood: Hard Mode (Team Size: 5) personal best: 22:03.20", "Tammz");
		assertEquals("Theatre of Blood", tob.get("boss"));
		assertEquals("Hard Mode", tob.get("mode"));
		assertEquals(5, tob.get("teamSize"));
		Map<String, Object> toa = ClanMessagesPlugin.parseClanPbAnnouncement(
			"Tammz has achieved a new Tombs of Amascut: Expert Mode (Team Size: 2) personal best: 27:10", "Tammz");
		assertEquals("Tombs of Amascut", toa.get("boss"));
		assertEquals("Expert Mode", toa.get("mode"));
		assertEquals(2, toa.get("teamSize"));
		Map<String, Object> boss = ClanMessagesPlugin.parseClanPbAnnouncement(
			"Tammz has achieved a new Vardorvis personal best: 1:23.40", "Tammz");
		assertEquals("Vardorvis", boss.get("boss"));
		assertEquals(83.4, (Double) boss.get("seconds"), 0.001);
	}

	@Test
	public void rejectsOtherPlayersAndAmbiguousGroupClanPbAnnouncements()
	{
		assertNull(ClanMessagesPlugin.parseClanPbAnnouncement(
			"Other player has achieved a new Chambers of Xeric (Team Size: Solo) personal best: 16:46", "Tammz"));
		assertNull(ClanMessagesPlugin.parseClanPbAnnouncement(
			"Tammz has achieved a new Chambers of Xeric personal best: 16:46", "Tammz"));
		assertNull(ClanMessagesPlugin.parseClanPbAnnouncement(
			"Tammz has achieved a new Chambers of Xeric (Team Size: Solo) personal best: 0:00", "Tammz"));
		assertNull(ClanMessagesPlugin.parseClanPbAnnouncement(
			"Tammz has achieved a new Chambers of Xeric (Team Size: 25) personal best: 16:46", "Tammz"));
		assertNull(ClanMessagesPlugin.parseClanPbAnnouncement(
			"Tammz has completed Chambers of Xeric in 16:46", "Tammz"));
	}

	@Test
	public void readsPhosaniSoloPbFromPlainGameMessage()
	{
		Map<String, Object> pb = ClanMessagesPlugin.parseChatNewPb(
			"Team size: Solo Fight duration: 4:31.20 (new personal best)");
		assertEquals(0, pb.get("teamSize"));
		assertEquals(271.2, (Double) pb.get("seconds"), 0.001);
		assertRaid("Phosani's Nightmare", "Phosani's Nightmare", "");
