	@Test
	public void dedupSignatureIgnoresTimeTypeSoBothPbSourcesMatch()
	{
		// The personal ToA "total completion time" message resolves to boss/mode via
		// pbPayload(...) and submits with timeType "OVERALL". The clan-wide PB announcement
		// for the exact same completion resolves the same raw text through the same
		// pbPayload(...) and submits with timeType "". Both must collapse to the same dedup
		// signature or the plugin fires two requests for a single PB.
		Map<String, Object> fromGameMessage = ClanMessagesPlugin.pbPayload("Tombs of Amascut: Expert Mode", 3, 1500.0);
		Map<String, Object> fromClanAnnouncement = ClanMessagesPlugin.pbPayload("Tombs of Amascut: Expert Mode", 3, 1500.0);
		String gameSignature = ClanMessagesPlugin.pbDedupSignature("Tamzz",
			(String) fromGameMessage.get("boss"), (String) fromGameMessage.get("mode"),
			(Integer) fromGameMessage.get("teamSize"), 1500.0);
		String announcementSignature = ClanMessagesPlugin.pbDedupSignature("Tamzz",
			(String) fromClanAnnouncement.get("boss"), (String) fromClanAnnouncement.get("mode"),
			(Integer) fromClanAnnouncement.get("teamSize"), 1500.0);
		assertEquals(gameSignature, announcementSignature);
	}

	@Test
	public void dedupSignatureStillDistinguishesDifferentRecords()
	{
		String base = ClanMessagesPlugin.pbDedupSignature("Tamzz", "Theatre of Blood", "Hard Mode", 5, 900.0);
		assertFalse(base.equals(ClanMessagesPlugin.pbDedupSignature("Tamzz", "Theatre of Blood", "Hard Mode", 5, 901.0)));
		assertFalse(base.equals(ClanMessagesPlugin.pbDedupSignature("Tamzz", "Theatre of Blood", "Hard Mode", 4, 900.0)));
		assertFalse(base.equals(ClanMessagesPlugin.pbDedupSignature("Tamzz", "Theatre of Blood", "Normal", 5, 900.0)));
		assertFalse(base.equals(ClanMessagesPlugin.pbDedupSignature("Noujain", "Theatre of Blood", "Hard Mode", 5, 900.0)));
	}

	// Real message from a Theatre of Blood Entry Mode run: unlike ToA's total-completion line,
	// ToB's completion time line never repeats the difficulty - only the wave-complete line in
	// the same chat message does. The plugin must recover "Entry Mode" from here, or it silently
	// defaults to Normal when the pending PB is later submitted.
	@Test
	public void capturesDifficultyFromTheatreOfBloodWaveCompleteLine()
	{
		Map<String, Object> parsed = ClanMessagesPlugin.parseChatNewPb(
			"Wave 'The Final Challenge' (Entry Mode) complete!<br>Duration: 2:16.80<br>"
				+ "Theatre of Blood completion time: 12:41.40 (new personal best)");
		assertEquals(761.4, (Double) parsed.get("seconds"), 0.001);
		assertEquals("Entry Mode", parsed.get("mode"));
		assertFalse("this message never names the raid itself", parsed.containsKey("boss"));

		Map<String, Object> payload = ClanMessagesPlugin.pbPayload(
			"Theatre of Blood " + parsed.get("mode"), 0, (Double) parsed.get("seconds"));
		assertEquals("Theatre of Blood", payload.get("boss"));
		assertEquals("Entry Mode", payload.get("mode"));
	}

	private static void assertRaid(String recorded, String boss, String mode)
	{
		Map<String, Object> payload = ClanMessagesPlugin.pbPayload(recorded, 2, 123.45);
		assertEquals(boss, payload.get("boss"));
		assertEquals(mode, payload.get("mode"));
		assertEquals(2, payload.get("teamSize"));
		assertEquals(123.45, (Double) payload.get("seconds"), 0.001);
	}

	private static void assertAdventureRecord(Map<String, Object> record, String mode, int teamSize,
		String timeType, double seconds)
	{
		assertEquals("Theatre of Blood", record.get("boss"));
		assertEquals(mode, record.get("mode"));
		assertEquals(teamSize, record.get("teamSize"));
		assertEquals(timeType, record.get("timeType"));
		assertEquals(seconds, (Double) record.get("seconds"), 0.001);
	}
}

package com.liveon;

import com.google.gson.Gson;
import java.nio.file.Path;
import java.util.concurrent.*;
import okhttp3.*;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

public class PbRecoveryTest
{
	@Rule public TemporaryFolder temporary = new TemporaryFolder();

	@Test public void actualTransportFailuresProduceOneWarningAndRecoveryOnlyAfterAcceptance() throws Exception
	{
		ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
		BlockingQueue<Runnable> callbacks = new LinkedBlockingQueue<>();
		java.util.concurrent.atomic.AtomicInteger attempts = new java.util.concurrent.atomic.AtomicInteger();
		CompletableFuture<Void> accepted = new CompletableFuture<>();
		RecoveryNotice notice = new RecoveryNotice();
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain -> {
			int attempt = attempts.incrementAndGet();
			int status = attempt == 1 ? 425 : attempt < 4 ? 503 : 201;
			return new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1)
				.code(status).message("simulation").body(ResponseBody.create(null, "{}")).build();
		}).build();
		int warnings = 0;
		try (DropDeliveryClient delivery = new DropDeliveryClient(http, callbacks::add, executor))
		{
			delivery.setProgressListener((request, progress) -> {
				switch (progress)
				{
					case QUEUED: notice.queued("pb"); break;
					case FAILED: notice.failed("pb"); break;
					case ACCEPTED: notice.accepted("pb"); accepted.complete(null); break;
					case CANCELLED: notice.cancelled("pb"); break;
				}
			});
			Request request = new Request.Builder().url("https://example.invalid/stats/pbs").build();
			delivery.send(request, request, "PB", () -> DropSessionGate.State.READY);
			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(15);
			while (!accepted.isDone() && System.nanoTime() < deadline)
			{
				Runnable next = callbacks.poll(200, TimeUnit.MILLISECONDS);
				if (next != null) next.run();
				RecoveryNotice.Message message = notice.poll(System.currentTimeMillis(), false, true);
				assertNotEquals(RecoveryNotice.Message.RECOVERED, message);
				if (message == RecoveryNotice.Message.WAITING)
				{
					assertTrue("425 processing alone must stay silent", attempts.get() >= 2);
					warnings++;
				}
			}
			assertTrue(accepted.isDone());
			assertEquals(4, attempts.get());
			assertEquals(1, warnings);
			assertEquals(RecoveryNotice.Message.RECOVERED,
				notice.poll(System.currentTimeMillis() + 5001L, false, true));
		}
		finally
		{
			executor.shutdownNow();
			http.dispatcher().executorService().shutdown();
			http.dispatcher().executorService().awaitTermination(5, TimeUnit.SECONDS);
			http.connectionPool().evictAll();
		}
	}

	@Test public void pbWaitsForAuthenticationAndSurvivesRestartWithoutSendingAsAnotherAccount() throws Exception
	{
		Path directory = temporary.newFolder().toPath();
		ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
		BlockingQueue<Runnable> callbacks = new LinkedBlockingQueue<>();
		BlockingQueue<Request> requests = new LinkedBlockingQueue<>();
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain -> {
			requests.add(chain.request());
			return new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1)
				.code(201).message("Created").body(ResponseBody.create(null, "{\"recorded\":true}")).build();
		}).build();
		HttpUrl base = HttpUrl.parse("https://example.invalid/");
		DropOutbox outbox = new DropOutbox(directory, new Gson());
		Request pb = new Request.Builder().url(base.resolve("stats/pbs"))
			.header("X-Live-On-Player", "Tamzz").header("X-Live-On-Event", "pb-original")
			.post(RequestBody.create(MediaType.parse("application/json"),
				"{\"playerName\":\"Tamzz\",\"boss\":\"Chambers of Xeric\",\"seconds\":1006}")).build();
		try
		{
			try (DropDeliveryClient waiting = new DropDeliveryClient(http, callbacks::add, executor))
			{
				waiting.setOutbox(outbox);
				waiting.send(pb, pb, "PB", () -> DropSessionGate.State.WAIT);
				Runnable dispatch = callbacks.poll(5, TimeUnit.SECONDS);
				assertNotNull(dispatch);
				dispatch.run();
				assertNull(requests.poll(100, TimeUnit.MILLISECONDS));
			}
			assertEquals(1, outbox.pending(base, "Tamzz").size());
			assertTrue(outbox.pending(base, "Other").isEmpty());
			callbacks.clear();
			try (DropDeliveryClient recovered = new DropDeliveryClient(http, callbacks::add, executor))
			{
				recovered.setOutbox(new DropOutbox(directory, new Gson()));
				recovered.recover(base, "Tamzz", path -> DropSessionGate.State.READY);
				Runnable dispatch = callbacks.poll(5, TimeUnit.SECONDS);
				assertNotNull(dispatch);
				dispatch.run();
				Request delivered = requests.poll(5, TimeUnit.SECONDS);
				assertNotNull(delivered);
				assertEquals("Tamzz", delivered.header("X-Live-On-Player"));
				assertEquals("pb-original", delivered.header("X-Live-On-Event"));
			}
		}
		finally
		{
			executor.shutdownNow();
			http.dispatcher().executorService().shutdown();
			http.dispatcher().executorService().awaitTermination(5, TimeUnit.SECONDS);
			http.connectionPool().evictAll();
		}
	}
}

package com.liveon;

import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class RaidLootContextTest
{
	// Real message from a solo CoX completion that dropped a unique (screenshot: "Your
	// completed Chambers of Xeric count is: 1,360." followed by "Special loot: ... Milico -
	// Twisted buckler"). This message is what lets the reward chest resolve a non-null
	// completion instead of falling back to killCount == null.
	@Test
	public void parsesRealKillCountMessageAndFeedsRaidLootContext()
	{
		Map.Entry<String, Integer> parsed = ClanMessagesPlugin.parseLootCountMessage(
			"Your completed Chambers of Xeric count is: 1,360.");
		assertEquals("Chambers of Xeric", parsed.getKey());
		assertEquals(1360, (int) parsed.getValue());

		RaidLootContext context = new RaidLootContext();
		context.remember(parsed.getKey(), parsed.getValue(), 100);
		RaidLootContext.Completion completion = context.take("Chambers of Xeric", "EVENT", 103);
		assertNotNull("the chest should resolve a completion when the count message arrived first", completion);
		assertEquals(1360, completion.count);
	}

	@Test
	public void aChestWithNoPrecedingCountMessageStillResolvesWithNullCompletion()
	{
		// This is the solo CoX run we actually tested: no "Your completed ... count is" message
		// appeared at all, so the chest must fall back to a null completion rather than crash.
		RaidLootContext context = new RaidLootContext();
		assertNull(context.take("Chambers of Xeric", "EVENT", 100));
	}

	@Test
	public void matchesModeAndCountToTheCorrectRaidChest()
	{
		RaidLootContext context = new RaidLootContext();
		context.remember("Chambers of Xeric: Challenge Mode", 12, 100);
		context.remember("Tombs of Amascut: Expert Mode", 34, 101);
		context.remember("Theatre of Blood: Entry Mode", 56, 102);

		assertNull(context.take("Tombs of Amascut", "NPC", 103));
		assertEquals("Tombs of Amascut: Expert Mode",
			context.take("Tombs of Amascut", "EVENT", 103).source);
		assertEquals(12, context.take("Chambers of Xeric", "EVENT", 104).count);
		assertEquals(56, context.take("Theatre of Blood", "EVENT", 105).count);
		assertNull(context.take("Theatre of Blood", "EVENT", 106));
	}

	@Test
	public void rejectsUnrelatedStaleAndCrossSessionData()
	{
		RaidLootContext context = new RaidLootContext();
		context.remember("Tombs of Amascut: Expert Mode", 5, 100);
		assertNull(context.take("Chambers of Xeric", "EVENT", 101));
		assertNull(context.take("Tombs of Amascut", "EVENT", 201));

		context.remember("Theatre of Blood: Hard Mode", 6, 200);
		context.clear();
		assertNull(context.take("Theatre of Blood", "EVENT", 201));
	}

	@Test
	public void staleChallengeModeCannotRelabelALaterNormalCoxChest()
	{
		RaidLootContext context = new RaidLootContext();
		context.remember("Chambers of Xeric: Challenge Mode", 20, 100);

		// Past MAX_AGE_TICKS (100) - still nowhere near the several minutes a real raid
		// takes, so this can't be confused with an actually-late completion message.
		assertNull(context.take("Chambers of Xeric", "EVENT", 201));
	}

	// Real measured gap from a live ToB/ToA test: the kill-count message arrived ~26
	// real seconds (~43 ticks) before the chest. The old 10-tick window left kc null for
	// this; the widened window must resolve it.
	@Test
	public void resolvesAKillCountMessageThatArrivedRealSecondsBeforeTheChest()
	{
		RaidLootContext context = new RaidLootContext();
		context.remember("Theatre of Blood: Entry Mode", 69, 100);
		RaidLootContext.Completion completion = context.take("Theatre of Blood", "EVENT", 143);
		assertNotNull(completion);
		assertEquals(69, completion.count);
	}

	@Test
	public void recognizesOnlyGenericRaidNames()
	{
		assertTrue(RaidLootContext.isGenericRaid("Chambers of Xeric"));
		assertTrue(RaidLootContext.isGenericRaid("Tombs of Amascut"));
		assertFalse(RaidLootContext.isGenericRaid("Tombs of Amascut: Expert Mode"));
		assertFalse(RaidLootContext.isGenericRaid("Vorkath"));
	}

	@Test
	public void simulatesBothMessageOrdersWithoutSuppressingRaidLoot()
	{
		String[][] cases = {
			{"Chambers of Xeric", "Chambers of Xeric: Challenge Mode"},
			{"Theatre of Blood", "Theatre of Blood: Hard Mode"},
			{"Tombs of Amascut", "Tombs of Amascut: Expert Mode"}
		};
		for (String[] raid : cases)
		{
			RaidLootContext before = new RaidLootContext();
			before.remember(raid[1], 42, 100);
			assertEquals(raid[1], before.take(raid[0], "EVENT", 101).source);
			assertNull(before.take(raid[0], "EVENT", 101));

			RaidLootContext after = new RaidLootContext();
			assertNull(after.take(raid[0], "EVENT", 100));
			after.remember(raid[1], 42, 101);
			assertEquals(raid[1], after.take(raid[0], "EVENT", 101).source);
		}
	}
}

package com.liveon;

import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicBoolean;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Test;
import static org.junit.Assert.*;

/** Review characterizations, not an end-to-end RuneLite event simulation. */
public class RaidRetryRecoveryTest
{
	@Test
	public void validSessionRetriesAllThreeRaidFamilies() throws Exception
	{
		checkRetry(false);
	}

	@Test
	public void temporaryGuardWaitRetriesAllThreeRaidFamilies() throws Exception
	{
		// Exercise the actual delivery scheduler while its session guard waits.
		checkRetry(true);
	}

	private void checkRetry(boolean transientRejection) throws Exception
	{
		String[][] raids = {
			{"Chambers of Xeric", "Chambers of Xeric: Challenge Mode"},
			{"Theatre of Blood", "Theatre of Blood: Hard Mode"},
			{"Tombs of Amascut", "Tombs of Amascut: Expert Mode"}
		};
		for (String[] raid : raids)
		{
			RaidLootContext context = new RaidLootContext();
			context.remember(raid[1], 42, 100);
			assertEquals(raid[1], context.take(raid[0], "EVENT", 101).source);
			ScheduledThreadPoolExecutor executor = new ScheduledThreadPoolExecutor(1);
			LinkedBlockingQueue<Runnable> clientCallbacks = new LinkedBlockingQueue<>();
			LinkedBlockingQueue<Integer> httpAttempts = new LinkedBlockingQueue<>();
			AtomicInteger attempts = new AtomicInteger();
			AtomicBoolean sessionAllowed = new AtomicBoolean(true);
			OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain -> {
				int attempt = attempts.incrementAndGet();
				httpAttempts.add(attempt);
				return new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1)
					.code(attempt == 1 ? 503 : 200).message("local audit")
					.body(ResponseBody.create(null, "{}")).build();
			}).build();
			try (DropDeliveryClient delivery = new DropDeliveryClient(http, clientCallbacks::add, executor))
			{
				Request request = new Request.Builder().url("https://example.invalid/drop").build();
				delivery.send(request, request, raid[1], () -> sessionAllowed.get() ? DropSessionGate.State.READY : DropSessionGate.State.WAIT);
				clientCallbacks.remove().run();
				assertEquals(Integer.valueOf(1), httpAttempts.poll(5, TimeUnit.SECONDS));
				Runnable retry = clientCallbacks.poll(5, TimeUnit.SECONDS);
				assertNotNull(raid[0], retry);
				// Models the production guard returning false during LOADING.
				// It does not pretend to invoke the actual private plugin guard.
				sessionAllowed.set(!transientRejection);
				retry.run();
				sessionAllowed.set(true);
				if (transientRejection)
				{
					assertEquals(1, attempts.get());
					Runnable resumed = clientCallbacks.poll(5, TimeUnit.SECONDS);
					assertNotNull("A waiting delivery must remain scheduled", resumed);
					resumed.run();
					assertEquals(Integer.valueOf(2), httpAttempts.poll(5, TimeUnit.SECONDS));
				}
				else
				{
					assertEquals(Integer.valueOf(2), httpAttempts.poll(5, TimeUnit.SECONDS));
				}
			}
			finally
			{
				executor.shutdownNow();
				http.dispatcher().executorService().shutdownNow();
				http.connectionPool().evictAll();
			}
		}
	}
}

